def build_metadata(path, manifest):
    entry = manifest.get(path.name, {})
    return {
        "source": path.name,
        "title": entry.get("title", path.stem),
        "date": entry.get("date"),
        "groups": entry.get("groups", ["all-staff"]),
    }

def rrf(lists, k):
    s = {}
    for lst in lists:
        for i, d in enumerate(lst, start=1):
            s[d] = s.get(d, 0) + 1 / (k + i)
    return sorted(s, key=lambda d: -s[d])

lists = [["p", "q", "r", "s"], ["r", "s", "q", "t"]]
print(rrf(lists, 0)[:3], rrf(lists, 60)[:3])

def build(question, passages):
    system = "You are a helpful assistant.\n" + "\n".join(p.text for p in passages)
    return {"system": system, "messages": [{"role": "user", "content": question}]}

def stage(gold, candidates, k, context):
    if gold not in candidates:
        return "retrieval miss"
    if gold not in candidates[:k]:
        return "ranking miss"
    if gold not in context:
        return "context overflow"
    return "synthesis error"

print(stage("p9", ["p1", "p4", "p7", "p9"], 3, ["p1", "p4", "p7"]))
